function updateAc(eleName, item, dataFields, clearText) {
	var ac = field('__' + eleName + '_ac');
	if (item) {
		set(eleName,item.value);
	}
	else {
		clear(eleName);
	}
	if (item) {
		if (clearText) { 
			ac.val(null);
		}
		else {
			ac.val(item.title);
		}
	}
	if (dataFields) {
		for(var i=0;i<dataFields.length;i++) {
			var tgt = dataFields[i].target;
			var src = dataFields[i].source;
			set(tgt,item.data[src]);
		}
	}
}
function autocomplete(eleName,dictName, minLength, dataFields, clearText, mustExist, createFunctionName, words, fromStart) {
	var ac = field('__' + eleName + '_ac');
	var noMessage = 0;
	if (createFunctionName) noMessage=1;
	var params = {
        dict_name: dictName,
        no_message: noMessage,
        min_length:minLength,
        words:words,
        from_start:fromStart,
    }
    if(has('__parent')) {
		params['eid']=get('__parent')
	}

	ac.autocomplete({
		source: function( request, response ) {
			params['term'] = request.term;

			jQuery.ajax({
	            url: "/api/dict",
	            dataType: "json",
	            data: params,
	            success: function(data) {
                        if(data.error) alert(data.error_text);
	                response(data.data);
	            }
			});
		},

		select: function( event, ui ) { 
			jQuery(this).selected=true; 
			ac.autocomplete('close');
			updateAc(eleName,ui.item,dataFields,clearText);
			return false;
		},
		focus: function(e, ui) {
    		return false;
		}
	}).keydown(function(e){
	if (e.keyCode === 13){
		jQuery("#edit-single-add-test").click();
	}
	});
	
	jQuery.ui.autocomplete.prototype._renderItem = function( ul, item ) {
		itemContent = null;
		if (item.message) {
			itemContent = item.html;
		}
		else {
			itemContent = '<a>' + item.html + '</a>';
		}
		return jQuery( '<li>' )
		.data( 'item.autocomplete', item )
		.append( itemContent )
		.appendTo( ul );
	}
	
}

function autocompleteList(eleName,dictName, minLength, createFunctionName) {
	var ac = field('__' + eleName + '_ac');
	var noMessage = 0;
	if (createFunctionName) noMessage=1;
	ac.autocomplete({
		source: function( request, response ) {
			jQuery.ajax({
	            url: "/add/api/dict.json",
	            dataType: "json",
	            data: {
	                term: request.term,
	                dict_name: dictName,
	                no_message: noMessage,
	                min_length:minLength
	            },
	            success: function(data) {
	                response(data.data);
	            }
			});
		},
		select: function( event, ui ) { 
			var ac = field('__' + eleName + '_ac');
            var item = ui.item;
            if (item) {
                    set(eleName,item.value);
                    ac.val(item.title);
            }
            ac.autocomplete('close');
            return false;
		},
		focus: function(e, ui) {
    		return false;
		}
	});
	ac.data('autocomplete')._renderItem = function( ul, item ) {
		itemContent = null;
		if (item.message) {
			itemContent = item.html;
		}
		else {
			itemContent = '<a>' + item.html + '</a>';
		}
		return jQuery( '<li>' )
		.data( 'item.autocomplete', item )
		.append( itemContent )
		.appendTo( ul );
	}
}

function checkAutocomplete(eleName,dictName) {
	var text = get('__' + eleName + '_ac');
	var matches = null;
	jQuery.ajax({
        url: "/api/dict",
        dataType: "json",
        data: {
            term: text,
            dict_name: dictName
        },
        success: function(fullData) {
        	if(!fullData) return;
        	var data = fullData.data;
        	if (data[0].title && data[0].title.toLowerCase()==text.toLowerCase()) {
            	for(var i=0;i<data.length;i++) {
					if (data[i].title.toLowerCase()==text.toLowerCase()) {
						matches = data[i];
						set("__" + eleName + "_ac",data[i].title);
						set(eleName,data[i].value);
					}
				}
            }
            if (!matches) {
		        if (get(eleName)=="") {
					if (get("__" + eleName + "_ac")=="") return;
					var yn=confirm("Test type was not found. Do you wish to create it?");
					
					if (yn==false) { clear('__' + eleName + '_ac'); return; }
				}
			}

			field('single_test').after('<input type="hidden" value="submit" name="single_add_test"/>');
			ADD.Notice.startWait();
			jQuery('#content-form').submit();
		}	   
	});
}

;ADD.User.AutoLogout = function() {
	function timedLogout() {
			jQuery(document).idleTimer.enabled=false;
			
			if($(".modal").is(":visible")) {
				$('modal').modal('hide');
			}
			var encForm = jQuery("#content-form");
			var isDirty = encForm.dirtyForms('isDirty');
				
				
			if (!isDirty) {
				autoLogout();
				return;
			}

			set('__autosave',1);
			$('#content-form :input').blur();

			if ($('.error').length) {
				set('__invalid',1);
			}
			jQuery(document).idleTimer.enabled=false;

			$.DirtyForms.disable();

			angular.element("body").scope().save().then(
				function() {
					autoLogout();
				}
			);

	};
	function autoLogout() {
		ADD.User.AutoLogout.autoLogout();
	};
	function showLogoutBox() {
		var message = "Sorry you have been logged out because you have been inactive for over 30 minutes. <br/>Click 'Log In' to log back in or close this window";
		ADD.Notice.showAlert("Auto Logout",message,"Log In", "/auth/login?dest=" + encodeURIComponent(window.location.href));
		$.DirtyForms.disable();

		//prevent users moving out of modal
		$('.modal-backdrop').unbind('click');
	}
	function checkLoggedIn() {
		jQuery.ajax({
			url:"/auth/loggedin",
			error: function (xhr, textStatus, errorThrown) {
				if(xhr.status==0) return;
				ADD.Notice.showAlert("Unexpected HTTP error","HTTP error " + xhr.status + "<br/>" + errorThrown);
			},
			success: function(data, textStatus) {
				if(!data['logged_in']) {
					showLogoutBox();
				}
			}
		});
	}
	return {
		"setup":function(secondsToWait) {
			var milliSecs = secondsToWait * 1000;
			$.idleTimer(milliSecs);
			$(document).on('idle.idleTimer', function(){ timedLogout() });
			var date = new Date();
			window.autoLogoutTime = date.getTime() + milliSecs + 1000;
		},
		"autoLogout":function() {
			$(".modal").modal('hide');
			var that = this;
			jQuery.ajax({
					url:"/auth/logout?" + ADD.Util.ts(),
					method:"GET",
					error: function (XMLHttpRequest, textStatus, errorThrown) {
							ADD.Notice.showAlert("Unexpected error","Error " + errorThrown);
					},
					success: function(data, textStatus) {
						$(document).off('idle.idleTimer');
					}
			}).then(function() {
				showLogoutBox();
			});
		}
	}
}();
