;ADD.Feature.ModalEntry = function() {
	return {
		"action": function(action) {
			if (!this.attrs.ajax)
				this.attrs.ajax = {"path": "/api/enc", "query": {}};
			screenHeight = jQuery(window).height();
			width = 800;
			height = 400;
			if (screenHeight <= 600)
				height = screenHeight - 150

			jQuery('.modal').css('margin-left', (width / 2) * -1);
			jQuery('.modal').css('margin-top', (screenHeight - height - 100) / 2);
			jQuery('.modal-body').css('height', height - 100);
			ADD.Notice.messageElement = "modal-messages-" + this.fieldName;

			elementId = "modal-" + this.fieldName;

			var capitalisedAction = action.substring(0, 1).toUpperCase() + action.substring(1);
			if (capitalisedAction == "Create")
				capitalisedAction = "Add";
			var heading = capitalisedAction + " " + this.attrs.description;
			ADD.Notice.removeAllErrors();
			jQuery('#' + elementId + ' .modal-header h3').html(heading);
			this.attrs.saveButtonId = this.fieldName + '_save_btn';
			this.attrs.closeButtonId = this.fieldName + '_close_btn';
			jQuery('#' + this.fieldName + '_save_btn').click(function() {
				modalSave(options)
			});
			jQuery('#' + this.fieldName + '_close_btn').click(function() {
				jQuery("#" + elementId).modal("hide");
			});

			if (action == 'delete') {
				var yn = confirm("Are you sure you wish to delete the  " + this.attrs.description + "?");
				if (!yn)
					return false;
			}
			set('__action', action)
			query = this.attrs.ajax.query;
			query.action = action;
			query.id = this.attrs.id;
			query.lid = this.attrs.lid;
			query.fid = this.attrs.fid;
			query.pid = this.attrs.pid;
			jQuery.ajax({
				url: this.attrs.ajax.path,
				data: query,
				dataType: "json",
				error: function(XMLHttpRequest, textStatus, errorThrown) {
					alert("There was an error attempting to get " + this.attrs.ajax.path);
				},
				success: function(data, textStatus) {
					ADD.Form.ignoreClearContent = true;
					if (data.error) {
						alert(data.error);
						return;
					}
					jQuery.each(data, function(index, value) {

						currField = field(index);

						set(index, value);
						currField.change();
						if (ADD.has(index)) {
							var ops = ADD.get(index);
							for (var o = 0; o < ops.length; o++) {
								var currOp = ops[o];
								if (currOp.ajaxGet) {
									currOp.value = value;
									currOp['ajaxGet'].call(currOp, value);
								}
							}
						}
					});


					jQuery('[no-view="1"]').each(function(index) {
						var ele = jQuery(this);
						if (action == 'view')
							ele.hide();
						else
							ele.show();
					});

					jQuery('.disable-on-update :input').each(function(index) {
						var ele = jQuery(this);
						if (action == 'view' || action == 'edit') {
							disable(ele.attr("name"));
						}
						else {
							enable(ele.attr("name"));
						}
					});

					if (action == 'view') {
						jQuery('#' + elementId + ' :input').each(function(index) {
							var ele = jQuery(this);
							//ele.attr('disabled','disabled');
							ele.attr('view-disabled', '1');
						});
						jQuery('#' + this.fieldName + '_save_btn').hide();
						jQuery('.clear-link').hide();
					}
					else {
						jQuery('[view-disabled="1"]').each(function(index) {
							var ele = jQuery(this);
							ele.removeAttr('disabled');
						});
						jQuery('#' + this.fieldName + '_save_btn').show();
						jQuery('.clear-link').show();
					}

					if (action != 'delete') {
						showEntry.call(null, data);
					}
					else {
						window.location.reload();
					}
					ADD.Form.ignoreClearContent = false;
				}
			});
			var that = this;
			var showEntry = function(data) {
				if (that.attrs.beforeFunctionName)
					that.attrs.beforeFunctionName();
				jQuery('#modal-' + that.fieldName).modal({'backdrop': 'static', 'keyboard': false});
				jQuery('#modal-' + that.fieldName).modal('show');
			}
		}
	};
}
;ADD.Feature.AjaxPopulate = function() {
    return {
        "init": function() {
            var noticePanel = new ADD.NoticePanel();
            noticePanel.setMessageElement(ADD.Notice.getMessageElement());

            this.setNoticePanel(noticePanel);
            var fields = this.attrs.fields;
            for (var f = 0; f < fields.length; f++) {
                field(fields[f]).on('change', this, function(event) {


                    event.data.refresh();
                });
            }

            this.refresh();
        },
        "getNoticePanel":function() {
            return this.noticePanel;
        },
        "setNoticePanel":function(noticePanel) {
            this.noticePanel = noticePanel;
        },
        "populateFromAjax": function(ajaxData) {
        	var outputs = ajaxData.outputs;
            var messages = ajaxData.messages;
            var fields = ajaxData.fields;
            this.invalid = false;
            var noticePanel = this.getNoticePanel();
            noticePanel.removeFieldWarnings(this.attrs.funcName);
            if (messages) {
                if (messages.warnings) {
                    for (var e = 0; e < messages.warnings.length; e++) {
                        noticePanel.addFieldWarning(this.attrs.funcName, messages.warnings[e]);
                    }
                }
                if (messages.errors) {
                    for (var e = 0; e < messages.errors.length; e++) {
                        var error = messages.errors[e];
                        noticePanel.removeFieldErrors(error.fieldName);
                        noticePanel.addFieldErrorWithLabel(error.fieldTitle, error.message, error.fieldName);
                        this.invalid = true;
                    }
                }
                if(messages.debug) {
                    $('.debug').append(messages.debug);
                }
            }

            if (!outputs)
                return ajaxData;

            var flds = _.keys(outputs);

            for (var f = 0; f < flds.length; f++) {
                var fld = flds[f];

                if(!has(fld)) {
                    continue;
                }
                var foutput = outputs[fld];

                if (!_.isObject(foutput)) {
                    var currValue = get(fld);
                    if(currValue == "" && foutput==null) {
                        continue;
                    }
                    if(currValue == foutput) {
                        continue;
                    }
                    set(fld, foutput);
                    continue;
                }

                if (foutput.content) {
                    var contentFld = content(fld);

                    contentFld.html(foutput.content);
                }
                if(foutput.script) {
                    var fscript = new Function(foutput.script);
                    fscript();
                }
                if (foutput.options) {

                    opts = foutput.options;
                    prevValue = get(fld);

                    var selectFld = field(fld);
                    selectFld.empty();

                    for (var c = 0; c < opts.length; c++) {
                        var optEle = '<option value=\"' + opts[c].value + '\"';
                        if (field(fld).attr('selvalue') == opts[c].value) {
                            optEle = optEle + ' selected=\"true\"';
                        }
                        field(fld).append(optEle + '>' + opts[c].label + '</option>');
                    }
                    set(fld, prevValue);
                    selectFld.dirtyForms("setClean");
                }

                if (foutput.value) {
                    set(fld, foutput.value);

                    var selectFld = field(fld);
                    selectFld.dirtyForms("setClean");
                }
            }
        },
        "refresh": function() {
            var inputs = jQuery("#" + ADD.Form.currentFormId).serializeArray();
            inputs.push({name: 'm', value: this.attrs.modName});
            inputs.push({name: 'p', value: this.attrs.pageName});
            inputs.push({name: 'f', value: this.attrs.funcName});
            inputs.push({name: 'field', value: this.fieldName});
            var eid = ADD.Util.getUrlVars('eid');
            if (eid) {
                inputs.push({name: 'eid', value: eid});
            }
            var pid = ADD.Util.getUrlVars('pid');
            inputs.push({name: 'pid', value: pid});
            that = this;

            var ajaxLoader = "<i class='fa fa-spinner fa-pulse fa-fw ajax-load fa-2x'></i>"
            field(that.fieldName).before(ajaxLoader)
            var async = true;
            if(that.attrs.sync) {
                async = false;
            }
            $.ajax({
                dataType: "json",
                url: "/ajax",
                data: inputs,
                async:async,
                success:function(data, textStatus, jqXHR) {
                    that.populateFromAjax(data);
                    $('.ajax-load').remove();
                }
            });
        }
    }
};
ADD.Feature.AjaxFieldUpdate = function() {
    return {
        "ajaxGet": function(value) {
            set(this.attrs['update_field'], value);
        },
        "validate": function() {
            if (field(this.fieldName).is(":visible"))
                return;
            var value = get(this.attrs['update_field']);
            set(this.fieldName, value);
        }
    }
}


;var ajaxTimeout = 10000;

function showDialog(closeOnCancel, functions, content, params, title, width, height, elementID, position) {
	// if 'content' begins with a / then get using AJAX and use the params hash
	screenHeight = jQuery(window).height();
	screenWidth = jQuery(window).width()
	width = 700;
	height = 400;
	if (screenWidth<=800) width=screenWidth-200;
	
	if (screenHeight<=600) height=screenHeight-150
	
	if (!elementID) elementID="patient_dialog";
	if (!position) position=position;
	var dia = jQuery('#' + elementID);
	jQuery('.modal').css('margin-left',(width/2)*-1);
	jQuery('.modal').css('margin-top',(screenHeight-height-100)/2);
	jQuery('.modal-body').css('height',height-100);
	dia.modal('show');
	jQuery('#' + elementID + " .modal-body").html("Loading..");
		jQuery.ajax({
				url:content,
				data:params,
				dataType: "json",
				error: function (XMLHttpRequest, textStatus, errorThrown) {
					var dia = jQuery('#' + elementID + " .modal-body");
					dia.html('<div class="messages error"><ul><li class="error-patient">' + errorThrown + '</ul></li></div>')
				},
				success: function(data, textStatus) {
					var dia = jQuery('#' + elementID  + " .modal-body");
					if (data.error) {
						dia.html('<div class="messages error"><ul><li class="error-patient">' + data.error + '</ul></li></div>');
						return;
					}
					dia.html("<h4>Click on a patient name to use that patient:</h4>");
					var tab = document.createElement("table");
					tab.setAttribute("class","table table-hover");
					
					var thead = document.createElement("thead");
					
					var tr = document.createElement("tr");
					var cols = data[0];
					for(var i=0;i<cols.length;i++) {
						var th = document.createElement("th");
						th.appendChild(document.createTextNode(cols[i]));
						tr.appendChild(th);
					}
					thead.appendChild(tr);
					
					var tbody = document.createElement("tbody");
					
					for(var r=1;r<data.length;r++) {
						var row = data[r];
						var tr = document.createElement("tr");
						tr.setAttribute("onmouseover","this.style.backgroundColor='lightgreen';");
						tr.setAttribute("onmouseout","this.style.backgroundColor='white';");
						tr.setAttribute("onclick","updateContactWithPatient('" + row[1] + "')");
						
						var info = row[0];
						for(var i=1;i<row.length;i++) {
							var td = document.createElement("td");
							if (row[i]!=null)  td.appendChild(document.createTextNode(row[i]));
							if (i==1) {
								for(var e in info) {
									var hi=document.createElement("input");
									hi.setAttribute("type","hidden");
									hi.setAttribute("name","patient" + row[1]);
									hi.setAttribute("id",e + "." + row[1]);
									if (info[e]!=null) hi.setAttribute("value",info[e]);
									td.appendChild(hi);
								}
							}
							tr.appendChild(td);
						}
						tbody.appendChild(tr);
					}
					tab.appendChild(thead);
					tab.appendChild(tbody);
					dia.append(tab);
					
				},
				timeout: ajaxTimeout,
				type: "get"
		});
}

function doShowDialog(closeOnCancel, functions, heading,width, height,elementID, position) {	
	var buttonHash;
	
	var dialogElement = jQuery("#" + elementID);
	
	if (closeOnCancel && !functions['Cancel']) {
		functions['Cancel'] = function(){
			jQuery("#" + elementID).dialog("close");
		};
	}
	jQuery("#" + elementID).dialog( {
		modal :true,
		draggable :false,
		resizable :false,
		overlay : {
			opacity :0.5,
			background :"black"
		},
		buttons :functions,
		width : width + 50,
		height :height + 100,
		title: heading,
		stack: true,
		position: position
	});
	jQuery("#" + elementID).dialog('open');
	jQuery("#" + elementID).data('title.dialog',heading);
}

function patientLookup() {
		var functions = {
		};
		showDialog(true, functions, getPatientLookupPath(),
		{
			id: getIdentifier(),
			fname: getFirstName(),
			lname: getLastName(),
			dob: getBirthDate()
		}
		, 'Search Patients', 600, 400, 'patient_dialog');
	}

	function showAjaxLoader(elementID,small) {
	var e = document.getElementById(elementID);
	var image="/images/ajax-loader.gif";

	if (small) image = "/images/small-ajax-loader.gif";
	
	if (small==1) {
		_ajaxElementID = elementID;
		_ajaxImage = e.src;
		e.src = image ;
		return;
	}
	else if (small==2) {
		e.innerHTML = "<center><img style='vertical-align:middle' src='"
			+ image + "></center>";
		return;
	}
		e.innerHTML = "<center><img style='vertical-align:middle' src='"
			+ image + "'></center>";
}


	
function updateContactWithPatient(identifier) {
	var fieldMap = getFieldMap();
	var patientFields = document.getElementsByName('patient' + identifier);
	var fieldsWithValue=0;
	var populateFunction = function() {
		for (var i = 0; i < patientFields.length; i++) {
			var temp = patientFields[i].id.split('.');
			var sourceFieldName = temp[0];
			var targetFieldName = fieldMap[sourceFieldName];
			if (typeof(targetFieldName)=="string") {
				var targetField = document.getElementById(targetFieldName);
				if (targetField) {
					if (targetField.value.length > 0) 
						fieldsWithValue++;
				}
			}
		}

		if (fieldsWithValue>0) {
			var ok = confirm("This patient already contains data.\nAre you sure you want to replace this with the selected patient details?");
			if (!ok) return;
		}
		
		populatePatient(identifier);
		jQuery("#patient_dialog .modal-body").html("");
		jQuery("#patient_dialog").modal("hide");
	};
	if (prePopulateCheck(identifier,populateFunction)) return;
}

function populatePatient(identifier) {
	var fieldMap = getFieldMap();
	var patientFields = document.getElementsByName('patient' + identifier);
	for(var i=0;i<patientFields.length;i++) {
		
		var temp = patientFields[i].id.split('.');
		var sourceFieldName = temp[0];

		var targetFieldName = fieldMap[sourceFieldName];
		if (!targetFieldName) continue;
		
		if (typeof(targetFieldName)=="string") {
			var targetField = document.getElementById(targetFieldName);
			if (!targetField) throw "Target field:" + targetFieldName + " was not found!";
			maxLength = targetField.getAttribute('maxlength');
			var srcValue = patientFields[i].value;
                        if(maxLength && srcValue.length>maxLength) {
                        	ADD.Notice.addFieldWarning(targetField.name,"'" + label(targetField.name) + "' is too long and has been truncated (from " + srcValue.length + " to " + maxLength + " characters)");
                            targetField.value = srcValue.substr(0,targetField.maxLength);
                            
                        }
                        else {
                            targetField.value = srcValue;
                        }
			//alert("field:" + targetFieldName + typeof(targetFieldName));
		}
		else {
			targetFieldName.call(null,patientFields[i].value);
		}
	}
	postPopulateCheck();
	jQuery('[name="patient' + identifier + '"]').remove();	
}

;
function getPatientLookupPath() {
	return "/lookup/pmi"
}
function getBirthDate() {
	return document.getElementById('edit-lookup-date-of-birth').value;
}

function getIdentifier() {
	return document.getElementById('edit-lookup-identifier').value;
}

function getFirstName() {
	return document.getElementById('edit-lookup-first-name').value
}

function getLastName() {
	return document.getElementById('edit-lookup-last-name').value
}

function getFieldMap() {
	var genderMap = {
			'M': 'edit-gender-m',
			'F': 'edit-gender-f'
	};
	return {
			main_pat_id: 'edit-identifier',
			nhs_number: 'edit-nhs-no',
			title: 'edit-title',
			last_name:'edit-last-name',
			first_name:'edit-first-name',
			dob:'edit-date-of-birth',
			gender:function(value) {
				set('gender',value);
			},
			ethnicity:function(value) {
				set('ethnic_group',value);
			},
			marital_status:function(value) {
				set('marital_status',value);
			},
			pat_addr1:'edit-address-line-1',
			pat_addr2:'edit-address-line-2',
			pat_addr3:'edit-address-line-3',
			postcode:'edit-postcode',
			homephone:'edit-home-phone',
			workphone:'edit-work-phone',
			date_of_death: 'edit-date-of-death',
			death_indicator:function(value) {
				set('deceased',value);
			},
			gp_local_code:'edit-local-code',
			gp_doh_code:'edit-doh-code',
			gp_practicecode:'edit-practice-code',
			gp_title:'edit-gp-title',
			gp_forename:'edit-gp-forename',
			gp_surname:'edit-gp-surname',
			gp_addr1:'edit-gp-address1',
			gp_addr2:'edit-gp-address2',
			gp_addr3:'edit-gp-address3',
			gp_addr4:'edit-gp-address4',
			gp_postcode:'edit-gp-postcode',
			gp_workphone:'edit-gp-workphone'
	};
}
function prePopulateCheck(identifier,populateFunction) {
	jQuery.ajax({
			url: "/api/patient",
			data:{'identifier':identifier},
			dataType: "json",
			error: function (XMLHttpRequest, textStatus, errorThrown) {
				alert("error"+textStatus);
			},
			success: function(data, textStatus) {
				ADD.Notice.removeAllErrors();
				if (data.length==0 || data.data.length==0) {
					populateFunction.call();
				}
				else {
					pat = data.data;
					jQuery("#patient-new-form").removeClass();
					
					if (pat['id']==get('__patient_id')) {
						populateFunction.call();
					}
					else {
						patLink = "/patient/demographics?pid=" + pat['id'];
						ADD.Notice.addFieldErrorWithLabel("","Sorry the patient cannot be selected as one with this S-number '" + pat['identifier'] + "'  (" + pat['first_name'] + " " + pat['last_name'] + ") already exists in ADD.<br/><br/> " +
								"<a href=\"javascript:;\" onclick=\"CLE.Client.gotoNgPage('" + patLink + "')\">View " + pat['first_name'] + " " + pat['last_name'] + "'s demographics in ADD</a>","patient_exists");
					}
				}
				jQuery("#patient_dialog").modal("hide");
				
			},
			timeout: ajaxTimeout,
			type: "get"
	});
}

function postPopulateCheck() {
	$('#tabs-tabs a[href="#personal"]').tab('show');
}



